using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;

namespace AkilliKisayol {
 internal static class InterfacePreview {
  static int checks;static readonly List<string> passed=new List<string>();
  static void Check(bool result,string name){if(!result)throw new Exception(name);checks++;passed.Add("PASS "+name);}
  sealed class Host:ISystemHost {
   public int Starts,Closes,Locks,Sends;public string FileName,Arguments;public bool Shell;public List<CloseTarget> Targets=new List<CloseTarget>();public bool RejectClose,FailScan;public ManualResetEvent ScanGate;
   public List<CloseTarget> Windows(){return Targets;}
   public bool Close(CloseTarget target){Closes++;return !RejectClose;}
   public void Start(string file,string arguments,bool shell){Starts++;FileName=file;Arguments=arguments;Shell=shell;}
   public void Lock(){Locks++;}public void Keys(int mods,int key){Sends++;}
   public string CheckUpdates(){if(ScanGate!=null)ScanGate.WaitOne(5000);if(FailScan)throw new InvalidOperationException("fixture connection failure");return "fixture updates: 3";}
  }
  static async Task SystemChecks(){
   foreach(string id in new[]{"shutdown","updates","close-apps","clipboard"}){var json=LocalLlm.Json().Serialize(new{status="ready",name="System fixture",trigger="Ctrl+Alt+F6",app_id="global",message="",notes=new string[0],steps=new[]{new{kind="system",combo="",text=id,ms=0}}});var plan=LlmProtocol.ReadPlan(json,new LlmRequest{Prompt="When I press Ctrl+Alt+F6, "+id,Trigger="Ctrl+Alt+F6",Applications=new List<string>()});Check(plan.Ready&&plan.Binding.Steps.Single().Kind=="System"&&plan.Binding.Steps.Single().Text==id,"Model plan accepts native system action without registered app: "+id);}
   Check(SystemActions.Catalog.Select(a=>a.Id).Distinct().Count()==SystemActions.Catalog.Length,"Unique action IDs");
   foreach(var spec in SystemActions.Catalog){var draft=MainWindow.RecommendedDraft(spec);Check(draft.Key==0&&draft.Gesture==null&&draft.AppPath=="","Preset has no implicit trigger: "+spec.Id);Check(Rules.Validate(draft,new Binding[0])!=null,"Unset trigger rejected: "+spec.Id);draft.Key=117;draft.Mods=3;Check(Rules.Validate(draft,new Binding[0])==null,"System action validates: "+spec.Id);var conflict=draft.Copy();conflict.Id=Guid.NewGuid().ToString();Check(Rules.Validate(conflict,new[]{draft})!=null,"Conflict checked: "+spec.Id);}
   Check(SystemActions.Validate("arbitrary-script")!=null,"Unknown action rejected");
   Check(WindowsSystemHost.Eligible("explorer",22,1,10,1,true,false,"Files","CabinetWClass"),"File Explorer windows can close without terminating the shell");Check(WindowsSystemHost.Eligible("ApplicationFrameHost",22,1,10,1,true,false,"Calculator","ApplicationFrameWindow"),"Visible packaged applications are supported");
   foreach(var id in new[]{"shutdown","restart"}){var host=new Host();await SystemActions.Run(id,host,s=>false,s=>{});Check(host.Starts==0,"Cancelled power action never executes: "+id);await SystemActions.Run(id,host,s=>true,s=>{});Check(host.Starts==1&&Path.IsPathRooted(host.FileName)&&Path.GetFileName(host.FileName)=="shutdown.exe"&&host.Arguments==(id=="shutdown"?"/s /t 0":"/r /t 0")&&!host.Arguments.Contains("/f")&&!host.Shell,"Power uses fixed non-forced command: "+id);}
   var close=new Host{Targets=new List<CloseTarget>{new CloseTarget{Name="Fixture",Title="Unsaved draft"}}};await SystemActions.Run("close-apps",close,s=>false,s=>{});Check(close.Closes==0,"Cancelled close leaves windows untouched");await SystemActions.Run("close-apps",close,s=>s.Contains("Unsaved draft"),s=>{});Check(close.Closes==1,"Close confirmation lists target windows");close.RejectClose=true;string rejected=await SystemActions.Run("close-apps",close,s=>true,s=>{});Check(rejected.Contains("0 / 1"),"Rejected close is reported");
   Check(!WindowsSystemHost.Eligible("explorer",22,1,10,1,true,false,"Desktop","Progman"),"Shell excluded");Check(!WindowsSystemHost.Eligible("editor",10,1,10,1,true,false,"Draft"),"Own process excluded");Check(!WindowsSystemHost.Eligible("editor",22,2,10,1,true,false,"Draft"),"Other session excluded");Check(!WindowsSystemHost.Eligible("editor",22,1,10,1,false,false,"Draft"),"Background window excluded");Check(!WindowsSystemHost.Eligible("editor",22,1,10,1,true,true,"Draft"),"Owned dialogs excluded");Check(WindowsSystemHost.Eligible("editor",22,1,10,1,true,false,"Draft"),"Visible user application eligible");
   foreach(var spec in SystemActions.Catalog.Where(a=>!a.Confirm&&a.Id!="updates")){var host=new Host();await SystemActions.Run(spec.Id,host,s=>{throw new Exception("Unexpected confirmation");},s=>{});Check(host.Starts+host.Sends+host.Locks==1,"Exactly one operation: "+spec.Id);}
   using(var gate=new ManualResetEvent(false)){var host=new Host{ScanGate=gate};var first=SystemActions.Run("updates",host,s=>true,s=>{});var second=await SystemActions.Run("updates",host,s=>true,s=>{});Check(second.Contains("already"),"Parallel update scan coalesced");gate.Set();Check((await first).Contains("3"),"Update scan result returned");}
   bool failure=false;try{await SystemActions.Run("updates",new Host{FailScan=true},s=>true,s=>{});}catch(InvalidOperationException){failure=true;}Check(failure,"Update failures propagate to the action history");Check((await SystemActions.Run("updates",new Host(),s=>true,s=>{})).Contains("3"),"Failed update scan releases its concurrency gate");
   bool unknown=false;try{await SystemActions.Run("bogus",new Host(),s=>true,s=>{});}catch(ArgumentException){unknown=true;}Check(unknown,"Invalid action never dispatched");
  }
  static void Pump(){Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));}
  static void PumpMessages(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(80)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static void Screenshot(Window window,string name){window.UpdateLayout();Pump();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name)))encoder.Save(output);}
  public static int Run(){string folder=AppDomain.CurrentDomain.BaseDirectory;try{
   SystemChecks().GetAwaiter().GetResult();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Theme.Install(app);Ui.Language="en";var state=new State{Language="en",Paused=true,ThemeId="graphite",Gestures=new GestureOptions{Enabled=false}};
   state.Bindings.Add(new Binding{Name="Music playback",Key=117,Mods=3,Kind="Media",Target="Play / pause"});state.Bindings.Add(new Binding{Name="Capture a screen region",Key=118,Mods=3,Kind="System",Target="screenshot"});
   var window=new MainWindow(state,Path.Combine(folder,"preview-settings.json"));app.MainWindow=window;window.Show();Pump();Screenshot(window,"home-en.png");window.ChangeLanguage("tr");Pump();Check(Storage.Read(Path.Combine(folder,"preview-settings.json")).Language=="tr","Language preference persisted");Check(Ui.T("Home")=="Ana sayfa","Turkish resource selected");Screenshot(window,"home-tr.png");window.ProductViewForTest("Recommended shortcuts");Screenshot(window,"recommendations-tr.png");window.ProductViewForTest("System actions");Screenshot(window,"system-tr.png");
   var keyboard=window.EngineForTest;var editor=new Editor(keyboard,null,new Binding[0],initial:MainWindow.RecommendedDraft(SystemActions.Find("shutdown"))){Owner=window};editor.Show();Pump();Check(editor.CurrentDraft().Kind=="System"&&editor.CurrentDraft().Target=="shutdown","System editor preserves action ID");Screenshot(editor,"system-editor-tr.png");editor.Close();
   var stepEditor=new StepEditor(new ActionStep{Kind="System",Text="updates"}){Owner=window};stepEditor.Show();Pump();Check(stepEditor.DraftForTest().Kind=="System"&&stepEditor.DraftForTest().Text=="updates","Macro step editor preserves system action selection");stepEditor.Close();
   using(var gestureEngine=new GestureEngine(keyboard,()=>state,()=>state.Bindings)){var gestureDialog=new GestureWindow(gestureEngine,keyboard,state,()=>new SystemShortcut[0],initialAction:MainWindow.RecommendedDraft(SystemActions.Find("updates"))){Owner=window};gestureDialog.Show();gestureDialog.RecordForTest(GesturePromptTests.Shape().Points);var shape=gestureDialog.DraftForTest();Check(shape.Kind=="System"&&shape.Target=="updates"&&shape.Gesture!=null&&shape.Key==0,"Recommended system action accepts a touchpad shape without a key");Check(Rules.Validate(shape,state.Bindings)==null,"Touchpad system action uses normal shape validation");Screenshot(gestureDialog,"system-touchpad-tr.png");gestureDialog.Close();}
   var fixture=new Window{Owner=window,Title="Makro+ close fixture",Width=300,Height=180};bool allow=false,cancelled=false;fixture.Closing+=(s,e)=>{if(!allow){cancelled=true;e.Cancel=true;}};fixture.Show();Pump();var native=new WindowsSystemHost();var closeTarget=new CloseTarget{Handle=new System.Windows.Interop.WindowInteropHelper(fixture).Handle,ProcessId=System.Diagnostics.Process.GetCurrentProcess().Id};Check(native.Close(closeTarget),"Native WM_CLOSE sent only to controlled fixture");PumpMessages();Check(cancelled&&fixture.IsVisible,"A native close request respects a cancelling application");allow=true;Check(native.Close(closeTarget),"Native close request can be retried");PumpMessages();Check(!fixture.IsVisible,"A consenting fixture closes normally");
   var input=new TextBox{Text="Home"};Ui.Apply(input);Check(input.Text=="Home","User text is never translated");var label=Theme.Text("");label.Text="Home";Check(label.Text=="Ana sayfa","Turkish label");Ui.Language="en";Ui.Apply(label);Check(label.Text=="Home","English label restored");Ui.Language="tr";
   window.ChangeLanguage("en");Pump();Check(Ui.T("Home")=="Home","English switch restores resources");window.ProductViewForTest("Recommended shortcuts");Screenshot(window,"recommendations-en.png");Theme.Apply("paper",false);window.ProductViewForTest("Home");Screenshot(window,"home-en-light.png");window.ChangeLanguage("tr");window.ProductViewForTest("Home");Screenshot(window,"home-tr-light.png");Check(window.ActualWidth>=1000,"Main window layout measured");
   File.WriteAllText(Path.Combine(folder,"recommendations.js"),"window.MAKRO_RECOMMENDATIONS="+LocalLlm.Json().Serialize(SystemActions.Catalog.Select(a=>new{id=a.Id,title=Ui.T(a.Title),description=Ui.T(a.Description),category=Ui.T(a.Category),confirmation=a.Confirm}))+";");window.Close();app.Shutdown();
   File.WriteAllLines(Path.Combine(folder,"interface-test-results.txt"),new[]{"PASS • "+checks+" checks","System dispatch used an injected fake host. Native WM_CLOSE was sent only to a controlled test window. No shutdown, lock, user application close, live update scan or key injection was performed."}.Concat(passed));return 0;
  }catch(Exception error){File.WriteAllText(Path.Combine(folder,"interface-test-results.txt"),"FAIL after "+checks+" checks\n"+error);return 1;}}
  public static int Headless(){try{SystemChecks().GetAwaiter().GetResult();File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"system-test-results.txt"),new[]{"PASS • "+checks+" checks"}.Concat(passed));return 0;}catch(Exception error){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"system-test-results.txt"),error.ToString());return 1;}}
  public static int UpdateScan(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"windows-update-test.txt");try{string result=new WindowsSystemHost().CheckUpdates();File.WriteAllText(path,"PASS • Online Windows Update search only; no download or installation.\n"+result);return 0;}catch(Exception error){File.WriteAllText(path,"FAILED • Windows Update search only; no download or installation.\n"+error);return 1;}}
  public static int Real(string modelPath){var results=new List<object>();string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"system-model-results.json");using(var model=new LocalLlm())try{var cases=new[]{new[]{"When I press Ctrl+Alt+F6, check Windows updates.","updates"},new[]{"When I press Ctrl+Alt+F7, close all open applications without force.","close-apps"},new[]{"When I press Ctrl+Alt+F8, shut down the computer after confirmation.","shutdown"},new[]{"When I press F9, copy the selected text.","copy"}};foreach(var test in cases){var watch=System.Diagnostics.Stopwatch.StartNew();var plan=model.AnalyzeAsync(new LlmRequest{Prompt=test[0],ModelPath=modelPath,Applications=new List<string>(),Options=new ModelOptions()},message=>{},CancellationToken.None).GetAwaiter().GetResult();bool correct=plan.Ready&&(test[1]=="copy"?plan.Binding.Steps.Count==1&&plan.Binding.Steps[0].Kind=="Key"&&plan.Binding.Steps[0].Key==67:plan.Binding.Steps.Count==1&&plan.Binding.Steps[0].Kind=="System"&&plan.Binding.Steps[0].Text==test[1]);results.Add(new{prompt=test[0],passed=correct,elapsedMs=watch.ElapsedMilliseconds,errors=plan.Errors,steps=plan.Binding==null?null:plan.Binding.Steps});if(!correct)throw new Exception("Unexpected system plan for "+test[1]+": "+model.LastResponse);}File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",executedActions=0,results=results}));return 0;}catch(Exception error){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",executedActions=0,error=error.ToString(),results=results}));return 1;}}
 }
}
